          failOnJsActionErrors: true,
        )).run();
        expect(File(cacheLog).existsSync(), isFalse);
        expect((await File(resetLog).readAsString()).trim(), 'reset');
      } finally {
        await tmp.delete(recursive: true);
      }
    });
  });
}

