  /// the Java-parity postJSAction error message (epam/dm.ai#585).
  String _ticketKeySuffix() {
    final key = _resolvedTicketData?['key'] ?? ticketData?['key'];
    return key is String && key.isNotEmpty ? ' for ticket $key' : '';
  }

